import { matchPath } from "react-router-dom";
import { ROUTES, resolveCollectionRoute } from "@/router/routes";

export type MemoScope = "home" | "explore" | "archived";

export const getMemoViewId = (name: string): string => {
  const parts = name.split("/");
  return parts.length === 4 ? parts[3] : name;
};

const cleanPathname = (value: string): string => {
  const pathname = value.split(/[?#]/, 1)[0] || ROUTES.HOME;
  return pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;
};

/** Lower-cased global pathname, so a Space-scoped URL compares like its global twin. */
const comparablePathname = (pathname: string): string => resolveCollectionRoute(pathname).pathname.toLowerCase();

export const isMemoScopeRoute = (pathname: string): boolean => {
  const comparablePath = comparablePathname(pathname);
  return comparablePath === ROUTES.HOME || comparablePath === ROUTES.EXPLORE || comparablePath === ROUTES.ARCHIVED;
};

/** `/calendar` and any month or day beneath it. */
export const isCalendarRoute = (pathname: string): boolean => {
  const comparablePath = comparablePathname(pathname);
  return comparablePath === ROUTES.CALENDAR || comparablePath.startsWith(`${ROUTES.CALENDAR}/`);
};

/**
 * Routes that render a memo collection the sidebar can narrow. Views, calendar days,
 * and tags apply in place on all of them.
 */
export const isMemoCollectionRoute = (pathname: string): boolean =>
  isMemoScopeRoute(pathname) || isCalendarRoute(pathname) || matchPath(ROUTES.MAP, comparablePathname(pathname)) !== null;

interface ResolveMemoScopeOptions {
  detailFrom?: string;
  memoArchived?: boolean;
  fallback?: MemoScope;
}

export const resolveMemoScope = (pathname: string, options: ResolveMemoScopeOptions = {}): MemoScope => {
  const cleanPath = cleanPathname(pathname);
  const comparablePath = comparablePathname(cleanPath);
  if (comparablePath === ROUTES.EXPLORE) return "explore";
  if (comparablePath === ROUTES.ARCHIVED) return "archived";
  if (comparablePath === ROUTES.HOME) return "home";

  if (comparablePath.startsWith("/memos/") && options.detailFrom) {
    return resolveMemoScope(options.detailFrom, {
      fallback: options.fallback,
    });
  }

  if (comparablePath.startsWith("/memos/") && options.memoArchived) {
    return "archived";
  }

  return options.fallback ?? "home";
};
import { describe, expect, it } from "vitest";
import { buildMemoFilter } from "@/hooks/useMemoFilters";
import { combineCELFilters } from "@/lib/cel-filter";
import { getMemoViewId, isMemoCollectionRoute, isMemoScopeRoute, resolveMemoScope } from "@/lib/memo-views";
import { Visibility } from "@/types/proto/api/memo_service_pb";

describe("memo scopes", () => {
  it("resolves collection and detail routes", () => {
    expect(resolveMemoScope("/archived")).toBe("archived");
    expect(resolveMemoScope("/explore")).toBe("explore");
    expect(resolveMemoScope("/memos/123", { detailFrom: "/archived?filter=tagSearch%3Awork" })).toBe("archived");
    expect(resolveMemoScope("/memos/123", { memoArchived: true })).toBe("archived");
    expect(resolveMemoScope("/settings", { fallback: "explore" })).toBe("explore");
  });

  it("recognizes Home, Archived, and the legacy Explore alias", () => {
    expect(isMemoScopeRoute("/")).toBe(true);
    expect(isMemoScopeRoute("/explore")).toBe(true);
    expect(isMemoScopeRoute("/archived")).toBe(true);
    expect(isMemoScopeRoute("/attachments")).toBe(false);
  });

  it("treats Home and calendar as collection routes where views and filters apply in place", () => {
    expect(isMemoCollectionRoute("/")).toBe(true);
    expect(isMemoCollectionRoute("/archived")).toBe(true);
    expect(isMemoCollectionRoute("/?creator=steven")).toBe(true);
    expect(isMemoCollectionRoute("/u/steven")).toBe(false);
    expect(isMemoCollectionRoute("/calendar")).toBe(true);
    expect(isMemoCollectionRoute("/Calendar/2026/08/02/")).toBe(true);
    expect(isMemoCollectionRoute("/calendars")).toBe(false);
    expect(isMemoScopeRoute("/u/steven")).toBe(false);
    expect(isMemoCollectionRoute("/memos/123")).toBe(false);
    expect(isMemoCollectionRoute("/attachments")).toBe(false);
  });
});

describe("memo views", () => {
  it("keeps OR expressions inside the author, Space, view, and facet constraints", () => {
    const query = 'content.contains("plan") || pinned';
    const filter = buildMemoFilter({
      creatorName: "users/steven",
      selectedMemoViewFilter: "has_link || has_code",
      filters: [
        { factor: "celSearch", value: query },
        { factor: "tagSearch", value: "work" },
      ],
      includePinned: true,
    });
    expect(combineCELFilters('space == "spaces/product"', filter)).toBe(
      '(space == "spaces/product") && ((creator == "users/steven") && (has_link || has_code) && (content.contains("plan") || pinned) && (tag in ["work"]))',
    );
  });
  it("extracts the saved view ID", () => {
    expect(getMemoViewId("users/steven/views/work")).toBe("work");
  });

  it("composes a saved task view with search, tags, creator, and visibility", () => {
    expect(
      buildMemoFilter({
        creatorName: "users/steven",
        selectedMemoViewFilter: "has_task_list && has_incomplete_tasks",
        filters: [
          { factor: "contentSearch", value: "plan" },
          { factor: "tagSearch", value: "work" },
        ],
        includePinned: false,
        visibilities: [Visibility.PUBLIC],
      }),
    ).toBe(
      '(creator == "users/steven") && (has_task_list && has_incomplete_tasks) && (content.contains("plan")) && (tag in ["work"]) && (visibility in ["PUBLIC"])',
    );
  });

  it("maps the Space audience without falling back to Private", () => {
    expect(
      buildMemoFilter({
        filters: [],
        includePinned: false,
        visibilities: [Visibility.PUBLIC, Visibility.PROTECTED, Visibility.SPACE],
      }),
    ).toBe('(visibility in ["PUBLIC", "PROTECTED", "SPACE"])');
  });

  it("maps property filter factors to their CEL flags", () => {
    expect(
      buildMemoFilter({
        filters: [
          { factor: "property.hasLink", value: "" },
          { factor: "property.hasTaskList", value: "" },
          { factor: "property.hasCode", value: "" },
          { factor: "property.hasLocation", value: "" },
          { factor: "property.hasAttachments", value: "" },
          { factor: "property.hasImage", value: "" },
        ],
        includePinned: false,
      }),
    ).toBe("(has_link) && (has_task_list) && (has_code) && (has_location) && (has_attachments) && (has_image)");
  });

  it("uses a saved memo view filter", () => {
    expect(
      buildMemoFilter({
        filters: [],
        includePinned: false,
        selectedMemoViewFilter: 'tag in ["work"]',
      }),
    ).toBe('(tag in ["work"])');
  });

  it("builds display-time filters from valid local calendar-day boundaries", () => {
    const start = new Date(2026, 7, 2);
    const end = new Date(start);
    end.setDate(end.getDate() + 1);

    expect(
      buildMemoFilter({
        filters: [{ factor: "displayTime", value: "2026-08-02" }],
        includePinned: false,
      }),
    ).toBe(
      `(created_ts >= timestamp(${Math.floor(start.getTime() / 1000)}) && created_ts < timestamp(${Math.floor(end.getTime() / 1000)}))`,
    );
  });

  it("selects on update time when that is the basis", () => {
    const start = new Date(2026, 7, 2);
    const end = new Date(start);
    end.setDate(end.getDate() + 1);

    expect(
      buildMemoFilter({
        filters: [{ factor: "displayTime", value: "2026-08-02" }],
        includePinned: false,
        timeBasis: "update_time",
      }),
    ).toBe(
      `(updated_ts >= timestamp(${Math.floor(start.getTime() / 1000)}) && updated_ts < timestamp(${Math.floor(end.getTime() / 1000)}))`,
    );
  });

  it("ignores invalid display-time filter values", () => {
    expect(
      buildMemoFilter({
        filters: [{ factor: "displayTime", value: "2026-02-30" }],
        includePinned: false,
      }),
    ).toBeUndefined();
  });
});

